import { defineConfig, devices } from '@playwright/test';

const APP_PORT = Number(process.env.ACTIVATION_REAL_APP_PORT ?? 4731);

/**
 * The activation portal against the REAL backend code.
 *
 * `playwright.activation.config.ts` runs the portal against a stand-in backend
 * transcribed from the backend's source. This runs the same portal against the
 * backend itself — its auth, device rules, validation, rate limits,
 * Serializable redemption, wallet ledger — on a throwaway local database with
 * a dedicated fixture student and cards generated by the backend's own admin
 * API. Nothing hosted is involved, and the helpers refuse anything that is not
 * on this machine.
 *
 * It is not started for you, because the backend lives in another repository:
 *
 *   1. Start the containers and the backend (see e2e/activation-real/backend-env.sh):
 *        . e2e/activation-real/backend-env.sh
 *        (cd "$BACKEND_DIR" && npx prisma migrate deploy && node dist/src/main.js) &
 *   2. Seed:   BACKEND_DIR=… node e2e/activation-real/seed.cjs
 *   3. Run:    BACKEND_DIR=… npx playwright test -c playwright.activation-real.config.ts
 *
 * The spec is one serial story (state accumulates in the backend), so re-seed
 * before every run.
 */
export default defineConfig({
  testDir: './e2e/activation-real',
  testMatch: /.*\.real\.ts/,
  fullyParallel: false,
  workers: 1,
  retries: 0,
  timeout: 120_000,
  expect: { timeout: 25_000 },
  reporter: [['list']],
  use: {
    baseURL: `http://127.0.0.1:${APP_PORT}`,
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
  webServer: [
    {
      command: 'node e2e/activation-real/dev.mjs',
      port: APP_PORT,
      reuseExistingServer: false,
      timeout: 240_000,
      env: { ACTIVATION_REAL_APP_PORT: String(APP_PORT) },
      stdout: 'ignore',
      stderr: 'pipe',
    },
  ],
});
